window.HH_CHUNKS=window.HH_CHUNKS||[];window.HH_CHUNKS[17]="`,bg:`data:image/jpeg;base64,`,a:'#f12f83',a2:'#f78fae',soft:'#fff0f6',wash:'#fff1f6',wash2:'#fff9fb',events:'8',goods:'4',sleep:'7h 28m',rest:'58 bpm',bp:'118/76',lunch:'540 kcal',steps:'7,842 steps',goal:'78%',insight:'Your activity and sleep show a strong positive trend this week.',k2lab:'❤ Pulzus',k2:'58',k2unit:'bpm',act:'7 842',goalH:'78% napi cél',docs:['Kardiológia kontroll','Szív UH lelet','EKG'],meds:['Entresto 24 mg','Concor Cor 2.5 mg','Forxiga 10 mg'],insH:'A pulzusod és az aktivitásod pozitív trendet mutat ezen a héten.',next:'2026-10-16',nextSub:'2 orvosi időpont'}};\nlet cur=localStorage.getItem('hh-profile')||'z', weather={temp:null,code:null,isDay:1,place:'Budapest'};\nfunction daypart(){let d=new Date(),m=d.getHours()*60+d.getMinutes();return(m>=300&&m<1080)?'day':(m>=1080&&m<1290)?'evening':'night'}\nfunction season(){let m=new Date().getMonth()+1;return(m>=3&&m<=5)?'spring':(m>=6&&m<=8)?'summer':(m>=9&&m<=11)?'autumn':'winter'}\nfunction heroBg(profile){let s=season(),d=daypart();return HERO_BG[profile]?.[s]?.[d]||HERO_BG[profile]?.[s]?.day||P[profile].bg}\n\nfunction weatherKind(c){\n  if(c===0)return'clear';\n  if([1,2].includes(c))return'partly';\n  if(c===3)return'cloudy';\n  if([45,48].includes(c))return'fog';\n  if([51,53,55,56,57].includes(c))return'drizzle';\n  if([61,63,65,66,67,80,81,82].includes(c))return'rain';\n  if([71,73,75,77,85,86].includes(c))return'snow';\n  if([95,96,99].includes(c))return'storm';\n  return'partly'\n}\nfunction weatherLabel(c){\n  if(c===0)return'Derült';\n  if(c===1)return'Többnyire derült';\n  if(c===2)return'Részben felhős';\n  if(c===3)return'Borult';\n  if([45,48].includes(c))return'Köd';\n  if([51,53,55,56,57].includes(c))return'Szitálás';\n  if([61,63,65,66,67].includes(c))return'Eső';\n  if([71,73,75,77].includes(c))return'Havazás';\n  if([80,81,82].includes(c))return'Zápor';\n  if([85,86].includes(c))return'Hózápor';\n  if([95,96,99].includes(c))return'Zivatar';\n  return'Változó'\n}\nfunction weatherEmoji(c,isDay){\n  const k=weatherKind(c),day=Number(isDay)===1;\n  let icon='🌤️';\n  if(k==='clear')icon=day?'☀️':'🌙';\n  else if(k==='partly')icon=day?'🌤️':'☁️';\n  else if(k==='cloudy')icon='☁️';\n  else if(k==='fog')icon='🌫️';\n  else if(k==='drizzle')icon='🌦️';\n  else if(k==='rain')icon='🌧️';\n  else if(k==='snow')icon='🌨️';\n  else if(k==='storm')icon='⛈️';\n  return `<span class=\"weatherIcon\" aria-hidden=\"true\">${icon}</span>`;\n}\nfunction renderWeather(){\n  if(weather.temp==null)return;\n  const html=`${weatherEmoji(weather.code,weather.isDay)}<span>${weather.temp}°C</span><span class=\"weatherSep\">·</span><span>${weatherLabel(weather.code)}</span>`;\n  weatherT.innerHTML=weatherH.innerHTML=weatherHome.innerHTML=html\n}\nfunction dateFmt(){let d=new Date();let full=new Intl.DateTimeFormat('hu-HU',{month:'long',day:'numeric',weekday:'short'}).format(d);dateT.textContent=dateH.textContent=dateHome.textContent=full+' · Budapest';shortDate.textContent=new Intl.DateTimeFormat('hu-HU',{month:'short',day:'numeric'}).format(d)}\nfunction apply(){let p=P[cur];document.documentElement.style.setProperty('--a',p.a);document.documentElement.style.setProperty('--a2',p.a2);document.documentElement.style.setProperty('--soft',p.soft);document.documentElement.style.setProperty('--wash',p.wash);document.documentElement.style.setProperty('--wash2',p.wash2);document.documentElement.style.setProperty('--hero',`url(\"${heroBg(cur)}\")`);personT.src=personH.src=p.img;nameT.textContent=nameH.textContent=p.name+'⌄';events.textContent=p.events;goods.textContent=p.goods;sleep.textContent=p.sleep;resthr.textContent=p.rest;bpT.textContent=bpH.textContent=p.bp;lunch.textContent=p.lunch;steps.textContent=p.steps;goalText.textContent=p.goal;goalBar.style.width=p.goal;insightT.textContent=p.insight;k2lab.textContent=p.k2lab;k2.textContent=p.k2;k2unit.textContent=p.k2unit;actH.textContent=p.act;goalH.textContent=p.goalH;[doc1,doc2,doc3].forEach((e,i)=>e.textContent=p.docs[i]);[med1,med2,med3].forEach((e,i)=>e.textContent=p.meds[i]);insightH.textContent=p.insH;nextH.textContent=p.next;nextSub.textContent=p.nextSub;personHome.src=p.img;nameHome.textContent=p.name+'⌄';todayTitle.textContent='✨ '+p.name+' Today';todayInsight.textContent=p.insH||p.insight;homeNext.textContent=p.next;homeNextSub.textContent=p.nextSub;renderDailySpark();closePicker()}\nfunction applyTime(){let dp=daypart();document.documentElement.style.setProperty('--hero',`url(\"${heroBg(cur)}\")`);[heroT,heroH,heroHome].forEach(h=>{h.classList.remove('night','evening');if(dp==='night')h.classList.add('night');if(dp==='evening')h.classList.add('evening')})}\nasync function getWeather(lat=47.4979,lon=19.0402,place='Budapest'){try{\n  let r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code,is_day&timezone=Europe%2FBudapest`,{cache:'no-store'});\n  if(!r.ok)throw new Error('weather');\n  let j=await r.json();\n  weather={temp:Math.round(j.current.temperature_2m),code:j.current.weather_code,isDay:j.current.is_day,place};\n  renderWeather()\n}catch(e){\n  weatherT.innerHTML=weatherH.innerHTML=weatherHome.innerHTML=`${weatherEmoji(2,daypart()!=='night'?1:0)}<span>Időjárás nem elérhető</span>`\n}}\n\nlet namedayText='…';\n\nfunction extractNamedays(data){\n  const candidates=[\n    data?.namedays?.hu,\n    data?.nameday?.hu,\n    data?.data?.namedays?.hu,\n    data?.data?.nameday?.hu,\n    data?.namedays,\n    data?.data?.namedays,\n    data?.names,\n    data?.data?.names\n  ];\n  for(const c of candidates){\n    if(Array.isArray(c)&&c.length)return c.map(String);\n    if(typeof c==='string'&&c.trim())return c.split(/[,;]+/).map(s=>s.trim()).filter(Boolean);\n    if(c&&typeof c==='object'){\n      const v=c.hu||c.HU;\n      if(Array.isArray(v)&&v.length)return v.map(String);\n      if(typeof v==='string'&&v.trim())return v.split(/[,;]+/).map(s=>s.trim()).filter(Boolean);\n    }\n  }\n  return [];\n}\n\nfunction renderNameday(names){\n  const list=(names||[]).filter(Boolean);\n  namedayText=list.length?list.slice(0,2).join(', '):'—';\n  const markup=`<span class=\"namedayIcon\" aria-hidden=\"true\">🎉</span><span>Névnap: ${namedayText}</span>`;\n  ['namedayT','namedayH','namedayHome'].forEach(id=>{const el=document.getElementById(id);if(el)el.innerHTML=markup});\n}\nasync function getNameday(){\n  const d=new Date(), month=String(d.getMonth()+1), day=String(d.getDate());\n  try{\n    const r=await fetch('./data/namedays.json',{cache:'no-store'});\n    if(r.ok){\n      const j=await r.json();\n      const names=j?.namedays?.[month]?.[day]||[];\n      if(names.length){renderNameday(names);return}\n    }\n  }catch(_){}\n  try{\n    const r=await fetch(`https://nameday.abalin.net/namedays?month=${month}&day=${day}&country=hu`,{cache:'no-store'});\n    if(r.ok){\n      const j=await r.json(), names=extractNamedays(j);\n      if(names.length){renderNameday(names);return}\n    }\n  }catch(_){}\n  renderNameday([]);\n}\n\nfunction initWeather(){getWeather();if(navigator.geolocation)navigator.geolocation.getCurrentPosition(p=>getWeather(p.coords.latitude,p.coords.longitude,'Itt'),()=>{},{enableHighAccuracy:false,timeout:5000,maximumAge:900000})}\n\nlet dailySparkData=null, briefingData=null;\n\nfunction currentDateISO(){\n  const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;\n}\nfunction signGlyph(sign){return sign==='Vízöntő'?'♒':'♍'}\n\nfunction renderDailySpark(){\n  if(!dailySparkData)return;\n  const key=cur==='m'?'monika':'zsolt', p=dailySparkData.profiles?.[key];\n  if(!p)return;\n  sparkHeadline.textContent=p.headline||'A mai Daily Spark 06:00-kor érkezik.';\n  sparkPerson.textContent=(cur==='m'?'Mónika':'Zsolt')+' napi előrejelzése';\n  sparkSignDate.textContent=`${signGlyph(p.sign)} ${p.sign} · ${new Intl.DateTimeFormat('hu-HU',{month:'long',day:'numeric'}).format(new Date())}`;\n  const s=p.sections||{};\n  sparkFocus.textContent=s.focus||'—';\n  sparkWork.textContent=s.workMoney||'—';\n  sparkRelations.textContent=s.relationships||'—';\n  sparkEnergy.textContent=s.energy||'—';\n  sparkEvening.textContent=s.evening||'—';\n  sparkLena.textContent=s.lenaThought||'—';\n}\n\nfunction renderBriefing(){\n  if(!briefingData)return;\n  briefHeadline.textContent=briefingData.headline||'A mai briefing 07:00 után lesz elérhető.';\n  briefDate.textContent=`${briefingData.date||currentDateISO()} · 07:00`;\n  const secs=briefingData.sections||[];\n  briefChips.innerHTML=secs.map((s,i)=>`<button class=\"briefChip\" onclick=\"document.getElementById('brief-${i}').scrollIntoView({behavior:'smooth',block:'start'})\">${s.title}</button>`).join('');\n  briefSections.innerHTML=secs.length?secs.map((s,i)=>`<div id=\"brief-${i}\" class=\"detailCard\"><h3>${s.title}</h3><ul>${(s.items||[]).map(x=>`<li>${x}</li>`).join('')}</ul></div>`).join(''):`<div class=\"detailCard\"><h3>📰 A mai briefing</h3><p>A mai briefing 07:00 után lesz elérhető.</p></div>`;\n  briefSources.innerHTML=(briefingData.sources||[]).map(s=>`<a class=\"sourceLink\" href=\"${s.url}\" target=\"_blank\" rel=\"noopener\">${s.publisher||'Forrás'} · ${s.title}</a>`).join('')||'<span style=\"font-size:8.5px;color:#72879a\">Forráslista a briefinggel együtt érkezik.</span>';\n}\n\nasync function loadDailyContent(){\n  try{const r=await fetch('./data/daily-spark.json',{cache:'no-store'});if(r.ok){dailySparkData=await r.json();renderDailySpark()}}catch(_){}\n  try{const r=await fetch('./data/daily-briefing.json',{cache:'no-store'});if(r.ok){briefingData=await r.json();renderBriefing()}}catch(_){}\n}\n\nfunction show(id){document.querySelectorAll('.page').forEach(e=>e.classList.remove('on'));const page=document.getElementById(id);if(page)page.classList.add('on');navTimelineBar.style.display=id==='timeline'?'grid':'none';navHealthBar.style.display=id==='health'?'grid':'none';navHomeBar.style.display=id==='home'?'grid':'none';navDetailBar.style.display=(id==='spark'||id==='briefing')?'grid':'none';scrollTo(0,0)}\nfunction openPicker(){overlay.classList.add('on')}function closePicker(){overlay.classList.remove('on')}function setProfile(p){cur=p;localStorage.setItem('hh-profile',p);apply()}\nlet tt;function toast(t){clearTimeout(tt);let x=document.getElementById('toast');x.textContent=t;x.classList.add('on');tt=setTimeout(()=>x.classList.remove('on'),1700)}\ndateFmt();apply();applyTime();initWeather();getNameday();loadDailyContent();show('home');setInterval(applyTime,60000);setInterval(()=>getWeather(),600000);setInterval(getNameday,1800000);setInterval(loadDailyContent,900000);\n</script></body></html>";